$root=dirname(__DIR__);$state=json_decode(file_get_contents($root.'/tmp/older-deployments-state.json'),true,512,JSON_THROW_ON_ERROR);$stage=$root.'/outputs/rollback-stock-restoration-20261112';$desired=[];
foreach(['stock-adjustment-20261029','stock-adjustment-list-20261029']as$name){$p=$state['packages'][$name];foreach($p['payload']as$path=>$data){$current=$state['current'][$path]??null;$before=$p['before'][$path]??null;if($current!==null&&$current!==$before&&$current!==$data)throw new RuntimeException('Inspect later stock changes: '.$path);$desired[$path]=$data;}}
$manifest=[];foreach($desired as$p=>$b64){$dest=$stage.'/files/'.$p;if(!is_dir(dirname($dest)))mkdir(dirname($dest),0775,true);file_put_contents($dest,base64_decode($b64));$old=$state['current'][$p]??null;$manifest[$p]=['before'=>$old===null?null:hash('sha256',base64_decode($old)),'after'=>hash_file('sha256',$dest)];}
